// 3.112 s after start; collection 87; a mixed pause (young + some old regions); eden was full;
// copying failed for lack of free regions; 1,490 MB used before, 1,210 after, 1,536 MB committed; 38 ms stopped.
// Not healthy: an evacuation failure with 1.2 GB still used means the live set barely fits.
static final Pattern PAUSE = Pattern.compile(
        "GC\\((\\d+)\\) (?:[yYO]: )?(Pause(?: [A-Z]\\w*)+)"   // id, ZGC prefix, kind
        + "((?: \\((?:[^()]|\\(\\))*\\))*)"                     // labels, (System.gc()) included
        + "(?: (\\d+)M->(\\d+)M\\((\\d+)M\\))?"                 // heap before -> after (committed)
        + " ([\\d.]+)ms$");                                     // the pause

